import{bt as e,n as t,ot as n,st as r}from"./chunks/framework.CxhjsvYc.js";var i=JSON.parse(`{"title":"Data catalogue and financial assumptions audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/DATA-AND-FINANCIAL-ASSUMPTIONS.html"}],["meta",{"property":"og:title","content":"Data catalogue and financial assumptions audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/DATA-AND-FINANCIAL-ASSUMPTIONS.html"}],["meta",{"name":"twitter:title","content":"Data catalogue and financial assumptions audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/DATA-AND-FINANCIAL-ASSUMPTIONS.md","filePath":"audits/DATA-AND-FINANCIAL-ASSUMPTIONS.md","lastUpdated":1794227887000}`),a={name:`audits/DATA-AND-FINANCIAL-ASSUMPTIONS.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="data-catalogue-and-financial-assumptions-audit" tabindex="-1">Data catalogue and financial assumptions audit <a class="header-anchor" href="#data-catalogue-and-financial-assumptions-audit" aria-label="Permalink to “Data catalogue and financial assumptions audit”">​</a></h1><h2 id="data-01-—-product-source-provenance-in-the-user-facing-workflow" tabindex="-1">DATA-01 — Product-source provenance in the user-facing workflow <a class="header-anchor" href="#data-01-—-product-source-provenance-in-the-user-facing-workflow" aria-label="Permalink to “DATA-01 — Product-source provenance in the user-facing workflow”">​</a></h2><p><strong>Current status: IMPLEMENTED on this branch; CI passed.</strong> Bank-level <code>research_status</code> and <code>dataset_reviewed_at</code> remain visible beside the bank selector and in the generated report. Product-level <code>source_url</code>, <code>source_effective_date</code>, <code>source_type</code> and source notes now flow from CSV rows through both web and CLI loaders, the <code>FDOption</code> metadata fields, worker booking snapshots and report generation. Source metadata is non-economic: it does not enter the financial economic-terms key or strategy decision logic.</p><p><strong>Report behaviour:</strong></p><ul><li>HTML booking instructions show source type, effective date and an HTTPS-only source link.</li><li>Product caveats/notes are available in a collapsible source-notes section and are HTML-escaped.</li><li>CLI booking ledger prints source type, effective date, HTTPS-only source URL and notes.</li><li>Missing effective dates or invalid/non-HTTPS source URLs are labelled not recorded rather than treated as verified.</li></ul><p><strong>Implementation:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/core/models.js" target="_blank" rel="noreferrer">FDOption metadata</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/web/app.js" target="_blank" rel="noreferrer">web loader</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/io/data-loader.js" target="_blank" rel="noreferrer">CLI loader</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/web/simulation-task.js" target="_blank" rel="noreferrer">worker metadata restoration</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/reporting/html.js" target="_blank" rel="noreferrer">HTML report</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/reporting/console.js" target="_blank" rel="noreferrer">console report</a>.</p><p><strong>Verification:</strong> worker round-trip tests assert product metadata survives; report tests assert source details, escaped notes and rejection of unsafe URL schemes; CLI loader tests verify the catalogue provenance fields. CI passed on the current implementation commit. Pending shipment to <code>dev</code>.</p><h2 id="data-02-—-senior-minor-selection-is-not-an-actual-depositor-eligibility-check" tabindex="-1">DATA-02 — Senior/minor selection is not an actual depositor eligibility check <a class="header-anchor" href="#data-02-—-senior-minor-selection-is-not-an-actual-depositor-eligibility-check" aria-label="Permalink to “DATA-02 — Senior/minor selection is not an actual depositor eligibility check”">​</a></h2><p><strong>Current status: CLOSED AS AN OWNER-CONFIRMED SCOPE DECISION.</strong> The toggles intentionally filter candidate products; FD Cal does not verify depositor age, guardian status or bank onboarding eligibility. Retain the disclosure and do not represent the toggles as verification.</p><p><strong>Severity: P2</strong></p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/configuration.js#L140-L148" target="_blank" rel="noreferrer">configuration.js L140-L148</a> includes senior/minor products when the corresponding boolean is true. The web form stores these booleans in <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L76-L88" target="_blank" rel="noreferrer">app.js L76-L88</a>. It does not collect depositor age or guardian status. The report explicitly states that catalogue age and guardian conditions are informational and are not verified (<a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/reporting/html.js#L219" target="_blank" rel="noreferrer">html.js L219</a>).</p><p><strong>Impact:</strong> the toggle means “include this customer segment&#39;s products”, not “verify that the depositor qualifies”. A user can include senior/minor rates without the application checking age thresholds, inclusive/exclusive boundaries or guardian requirements.</p><p><strong>Recommendation:</strong> either:</p><ol><li>Add a customer eligibility profile (age on booking date, citizenship/residency where required, guardian confirmation) and enforce catalogue conditions; or</li><li>Rename the controls to make their scope unmistakable (“Include senior-citizen products in the candidate set”) and keep a persistent warning that eligibility is not checked.</li></ol><p>Do not imply that a category toggle is proof of eligibility.</p><h2 id="data-03-—-the-active-fd-model-cannot-yet-represent-all-special-product-constraints" tabindex="-1">DATA-03 — The active FD model cannot yet represent all special-product constraints <a class="header-anchor" href="#data-03-—-the-active-fd-model-cannot-yet-represent-all-special-product-constraints" aria-label="Permalink to “DATA-03 — The active FD model cannot yet represent all special-product constraints”">​</a></h2><p><strong>Current status: DEFERRED.</strong> No owner-approved scope for modelling the special-product constraints has been supplied. Keep products with unenforced simulation-critical constraints outside the active catalogue.</p><p><strong>Evidence:</strong> the research register <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/data/fd_options/age_eligibility.csv" target="_blank" rel="noreferrer">age_eligibility.csv</a> contains fields such as <code>product_max_amount</code> and <code>tax_exempt</code>. The active <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/models.js" target="_blank" rel="noreferrer">FDOption model</a> and data loaders currently model minimum amount and age/segment fields, but not product maximum amount or tax-exempt treatment.</p><p><strong>Impact:</strong> products with scheme-wide caps, product caps or special tax treatment must remain excluded from simulation until those rules can be enforced. Reusing general FD rates or minimums for a special product can create an invalid plan.</p><p><strong>Recommendation:</strong> extend the domain model only when a real product requires it: maximum amount, per-customer/scheme-wide cap, tax treatment, required documentation/guardian and any renewal/eligibility conditions. Add validation and tests before moving a research-register row into the active product catalogue.</p><h2 id="data-04-—-csv-rows-require-strict-structural-validation" tabindex="-1">DATA-04 — CSV rows require strict structural validation <a class="header-anchor" href="#data-04-—-csv-rows-require-strict-structural-validation" aria-label="Permalink to “DATA-04 — CSV rows require strict structural validation”">​</a></h2><p><strong>Current status: IMPLEMENTED on this branch; CI passed.</strong> The parser now rejects malformed quote placement, unterminated quoted fields, characters after a closing quote, and rows whose field count differs from the header. Errors include the source path and physical line number. The parser retains support for UTF-8 BOM, LF/CRLF, quoted commas, escaped quotes, multiline fields, and legitimate trailing empty cells.</p><p><strong>Inventory and data corrections:</strong> all 33 checked-in catalogue CSV files were inventoried and are covered by a regression test. The inventory found 93 malformed rows across three files:</p><ul><li><code>data/banks/banks.csv</code>: 26 rows had unquoted commas in <code>fee_basis</code>, which shifted/truncated <code>fee_source_url</code>.</li><li><code>data/fd_options/banks/LK_COMMERCIAL_BANK_OF_CEYLON.csv</code>: 43 rows had unquoted commas in the final <code>notes</code> field.</li><li><code>data/fd_options/banks/LK_DFCC_BANK.csv</code>: 24 rows had unquoted commas in the final <code>notes</code> field.</li></ul><p>Those fields are now correctly quoted. The bank fee source URL and product provenance notes remain in their intended columns.</p><p><strong>Implementation:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/io/csv.js" target="_blank" rel="noreferrer">strict parser</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/tests/js/csv.test.js" target="_blank" rel="noreferrer">CSV regression tests</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/data/banks/banks.csv" target="_blank" rel="noreferrer">bank metadata</a>.</p><p><strong>Acceptance:</strong> exact row width and valid CSV quoting are enforced; all 33 current catalogue files parse; malformed input fails with actionable source/line context. Pending shipment from this working branch to <code>dev</code>.</p><h2 id="data-05-—-transfer-fee-assumptions-are-not-a-full-transfer-channel-model" tabindex="-1">DATA-05 — Transfer-fee assumptions are not a full transfer-channel model <a class="header-anchor" href="#data-05-—-transfer-fee-assumptions-are-not-a-full-transfer-channel-model" aria-label="Permalink to “DATA-05 — Transfer-fee assumptions are not a full transfer-channel model”">​</a></h2><p><strong>Current status: DOCUMENTED LIMITATION — owner confirmed simplified model.</strong> No channel/tier/privilege model is planned in this pass; keep fees explicitly described as estimates. Regulatory and bank tariff examples are recorded in <a href="./OWNER-FEEDBACK-RESEARCH.html">owner-feedback research</a>.</p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/data/banks/banks.csv" target="_blank" rel="noreferrer">data/banks/banks.csv</a> records bank fee values and notes that distinguish online/mobile CEFT, OTC, SLIPS, fallback CBSL maxima and assumptions. The active fee model chooses same-bank or domestic inter-bank fees per source bank; it does not model all channels, transaction tiers, customer privileges or limits.</p><p><strong>Impact:</strong> a single fee per bank/channel class can be a useful planning approximation, but it is not a complete bank tariff model. The catalogue itself records conflicts and fallback assumptions (for example, bank-published values that differ from a CBSL digital CEFT maximum).</p><p><strong>Recommendation:</strong> keep the current model labelled “estimated transfer fee”. If channel selection materially changes outcomes, add a transfer method dimension (digital CEFT, OTC CEFT, SLIPS, internal transfer), transaction tier and effective date. Do not resolve contradictory sources by silently selecting one.</p><h2 id="data-06-—-bank-rate-freshness-and-secondary-sources-need-a-visible-warning-policy" tabindex="-1">DATA-06 — Bank-rate freshness and secondary sources need a visible warning policy <a class="header-anchor" href="#data-06-—-bank-rate-freshness-and-secondary-sources-need-a-visible-warning-policy" aria-label="Permalink to “DATA-06 — Bank-rate freshness and secondary sources need a visible warning policy”">​</a></h2><p><strong>Current status: METADATA CONTRACT IMPLEMENTED; SOURCE REVIEW PENDING.</strong> Freshness warnings use only <code>dataset_reviewed_at</code> (due at 180 days; stale at 365). The index separately records <code>dataset_updated_at</code> for material economic-data changes and <code>dataset_schema_version</code> for structural migrations. Schema-only migrations preserve both dates. All 29 indexed banks still have blank review/update dates because no source recheck has yet justified populating them. Do not infer dates from Git or file timestamps. See the <a href="./../data/BANK-DATA-METADATA.html">metadata contract</a> and <a href="./OWNER-FEEDBACK-RESEARCH.html">owner-feedback research</a>.</p><p>The index distinguishes <code>populated_direct</code>, <code>populated_secondary</code>, <code>no_public_rate_verified</code> and other research statuses. The web UI disables only the last category. A populated secondary compilation is usable by the engine but should not look identical to a current official schedule.</p><p><strong>Recommendation:</strong> define a freshness policy: effective date required where available, review age threshold, source priority, fallback handling, and visible warnings for secondary or undated rows. Do not automatically disable all secondary data if it remains useful; make confidence and provenance explicit.</p><h2 id="additional-catalogue-checks" tabindex="-1">Additional catalogue checks <a class="header-anchor" href="#additional-catalogue-checks" aria-label="Permalink to “Additional catalogue checks”">​</a></h2><ul><li>Keep rate rows with unresolved product mapping or minimum amounts out of the simulation catalogue, as current research notes already do.</li><li>Do not infer senior rates from general FD rates.</li><li>Preserve product-level labels and payout frequency; avoid flattening different payout contracts into one option.</li><li>Validate duplicate product identities and suspiciously identical rows during catalogue build.</li><li>Keep bank fees and FD rates independently sourced; a verified rate does not imply a verified fee.</li><li>Treat <code>age_eligibility.csv</code> as a research register until every simulation-critical term is enforceable by the engine.</li></ul>`,38)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};